export default function prepare({ body, headers, secret, fieldId, projectId, issueTypeId }) {
  if (typeof secret !== "string" || secret.length < 24 || headers?.["x-splunk-secret"] !== secret)
    throw Error("Invalid alert secret");
  const original = body?.inputs?.A?.key?.["host.name"];
  if (typeof original !== "string" || !original.trim()) throw Error("Alert host is required");
  const host = original.replace(/[^a-zA-Z0-9 ]/g, "");
  if (!host.trim()) throw Error("Host is empty after normalization");
  if (!/^customfield_\d+$/.test(fieldId)) throw Error("Set the Jira custom field ID");
  if (!/^\d+$/.test(projectId) || !/^\d+$/.test(issueTypeId))
    throw Error("Set numeric Jira project and issue type IDs");
  const description = typeof body.description === "string" ? body.description : "",
    message = typeof body.messageBody === "string" ? body.messageBody : "",
    timestamp = typeof body.timestamp === "string" ? body.timestamp : "";
  return {
    jql: `cf[${fieldId.slice(12)}] ~ "${host}"`,
    projectId,
    issueTypeId,
    summary: `Splunk Alert for host ${original}:  ${description}`,
    description: `${description}\n\n${message}`,
    extraFields: { [fieldId]: host },
    comment: `Timestamp: ${timestamp}\nDescription: ${description}`,
  };
}

