export default function next({ issues, previousState, comment }) {
  const index = previousState === null ? 0 : previousState.index + 1;
  if (index >= issues.length) return { state: { index }, more: false, issueKey: "-", comment };
  const key = issues[index]?.key;
  if (typeof key !== "string" || !key) throw Error("Search returned an issue without a key");
  return { state: { index }, more: true, issueKey: key, comment };
}
